@using sv_8802236cd24a49869a73cdf9b1468962.Services

<h5 class="mb-3">Cover Letter</h5>

<div class="mb-2">
    <textarea class="form-control" rows="12" maxlength="@MaxLength"
              @bind="CoverLetter" @bind:event="oninput"></textarea>
</div>
<div class="text-muted small text-end mb-3">
    @(CoverLetter?.Length ?? 0) / @MaxLength characters
</div>

<div class="d-flex justify-content-between mt-4">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="() => OnNext.InvokeAsync()">Next</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
}

@using sv_8802236cd24a49869a73cdf9b1468962.Services

@if (IsSubmitted)
{
    <div class="text-center py-5">
        <div class="display-1 text-success mb-3">✓</div>
        <h3>Application Submitted!</h3>
        <p class="text-muted">Your application ID is <strong>#@ApplicationId</strong></p>
        <p>Thank you for applying. We will be in touch soon.</p>
    </div>
}
else
{
    <h5 class="mb-4">Review Your Application</h5>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <!-- Personal Info -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <a href="" @onclick="() => OnEditSection.InvokeAsync(1)" @onclick:preventDefault class="small">Edit</a>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6"><strong>Name:</strong> @Personal.FullName</div>
                <div class="col-md-6"><strong>Email:</strong> @Personal.Email</div>
                <div class="col-md-6"><strong>Phone:</strong> @Personal.Phone</div>
                <div class="col-md-6"><strong>Address:</strong> @Personal.Address</div>
            </div>
        </div>
    </div>

    <!-- Work History -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <a href="" @onclick="() => OnEditSection.InvokeAsync(2)" @onclick:preventDefault class="small">Edit</a>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkEntries)
            {
                <div class="mb-3 pb-3 border-bottom last-no-border">
                    <div><strong>@entry.Title</strong> at @entry.Company</div>
                    <div class="text-muted small">
                        @entry.StartDate?.ToString("MMM yyyy")
                        – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <div class="mt-1">@entry.Description</div>
                    }
                </div>
            }
        </div>
    </div>

    <!-- References -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <a href="" @onclick="() => OnEditSection.InvokeAsync(3)" @onclick:preventDefault class="small">Edit</a>
        </div>
        <div class="card-body">
            @foreach (var reference in References)
            {
                <div class="mb-2">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    <span class="text-muted">@reference.Email · @reference.Phone</span>
                </div>
            }
        </div>
    </div>

    <!-- Cover Letter -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Cover Letter</strong>
            <a href="" @onclick="() => OnEditSection.InvokeAsync(4)" @onclick:preventDefault class="small">Edit</a>
        </div>
        <div class="card-body">
            <p style="white-space: pre-wrap;">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(No cover letter provided)" : CoverLetter)</p>
        </div>
    </div>

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Submit Application
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;

        try
        {
            var application = new JobApplication(
                Personal.ToRecord(),
                new WorkHistory(WorkEntries.Select(e => e.ToRecord()).ToList()),
                References.Select(r => r.ToRecord()).ToList(),
                CoverLetter);

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception)
        {
            ErrorMessage = "An error occurred while submitting your application. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

@page "/apply"
@using sv_8802236cd24a49869a73cdf9b1468962.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 1:
            <PersonalInfoStep Model="_personalInfo"
                              ApplicationService="ApplicationService"
                              OnNext="() => AdvanceStep(2)" />
            break;

        case 2:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="() => AdvanceStep(3)"
                             OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <ReferencesStep References="_references"
                            OnNext="() => AdvanceStep(4)"
                            OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <CoverLetterStep @bind-CoverLetter="_coverLetter"
                             OnNext="() => AdvanceStep(5)"
                             OnBack="() => GoToStep(3)" />
            break;

        case 5:
            <ReviewStep Personal="_personalInfo"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="_coverLetter"
                        ApplicationService="ApplicationService"
                        OnEditSection="GoToStep"
                        OnBack="() => GoToStep(4)" />
            break;
    }
</div>

@code {
    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = [];

    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new WorkEntryModel()];
    private readonly List<ReferenceModel> _references = [new ReferenceModel(), new ReferenceModel()];
    private string _coverLetter = "";

    private void AdvanceStep(int nextStep)
    {
        _completedSteps.Add(_currentStep);
        _currentStep = nextStep;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }
}

